# ! [doc = " SGX-specific extensions to general I/O primitives"] # ! [doc = ""] # ! [doc = " SGX file descriptors behave differently from Unix file descriptors. See the"] # ! [doc = " description of [`TryIntoRawFd`] for more details."] # ! [unstable (feature = "sgx_platform" , issue = "56975")] use split_decls_genesis :: ourprelude :: * ; use crate :: net ; pub use crate :: sys :: abi :: usercalls :: raw :: Fd as RawFd ; use crate :: sys :: { self , AsInner , FromInner , IntoInner , TryIntoInner } ; #[doc = " A trait to extract the raw SGX file descriptor from an underlying"] #[doc = " object."] #[unstable (feature = "sgx_platform" , issue = "56975")] pub trait AsRawFd { #[doc = " Extracts the raw file descriptor."] #[doc = ""] #[doc = " This method does **not** pass ownership of the raw file descriptor"] #[doc = " to the caller. The descriptor is only guaranteed to be valid while"] #[doc = " the original object has not yet been destroyed."] #[unstable (feature = "sgx_platform" , issue = "56975")] fn as_raw_fd (& self) -> RawFd ; } #[doc = " A trait to express the ability to construct an object from a raw file"] #[doc = " descriptor."] #[unstable (feature = "sgx_platform" , issue = "56975")] pub trait FromRawFd { #[doc = " An associated type that contains relevant metadata for `Self`."] type Metadata : Default ; #[doc = " Constructs a new instance of `Self` from the given raw file"] #[doc = " descriptor and metadata."] #[doc = ""] #[doc = " This function is typically used to **consume ownership** of the"] #[doc = " specified file descriptor. When used in this way, the returned object"] #[doc = " will take responsibility for closing it when the object goes out of"] #[doc = " scope."] #[doc = ""] #[doc = " However, consuming ownership is not strictly required. Use a"] #[doc = " [`From<OwnedFd>::from`] implementation for an API which strictly"] #[doc = " consumes ownership."] #[doc = ""] #[doc = " # Safety"] #[doc = ""] #[doc = " The `fd` passed in must be an [owned file descriptor][io-safety];"] #[doc = " in particular, it must be open."] #[doc = ""] #[doc = " [io-safety]: io#io-safety"] #[unstable (feature = "sgx_platform" , issue = "56975")] unsafe fn from_raw_fd (fd : RawFd , metadata : Self :: Metadata) -> Self ; } #[doc = " A trait to express the ability to consume an object and acquire ownership of"] #[doc = " its raw file descriptor."] #[unstable (feature = "sgx_platform" , issue = "56975")] pub trait TryIntoRawFd : Sized { #[doc = " Consumes this object, returning the raw underlying file descriptor, if"] #[doc = " this object is not cloned."] #[doc = ""] #[doc = " This function **transfers ownership** of the underlying file descriptor"] #[doc = " to the caller. Callers are then the unique owners of the file descriptor"] #[doc = " and must close the descriptor once it's no longer needed."] #[doc = ""] #[doc = " Unlike other platforms, on SGX, the file descriptor is shared between"] #[doc = " all clones of an object. To avoid race conditions, this function will"] #[doc = " only return `Ok` when called on the final clone."] #[unstable (feature = "sgx_platform" , issue = "56975")] fn try_into_raw_fd (self) -> Result < RawFd , Self > ; } impl AsRawFd for net :: TcpStream { #[inline] fn as_raw_fd (& self) -> RawFd { * self . as_inner () . as_inner () . as_inner () . as_inner () } } impl AsRawFd for net :: TcpListener { #[inline] fn as_raw_fd (& self) -> RawFd { * self . as_inner () . as_inner () . as_inner () . as_inner () } } #[doc = " Metadata for `TcpStream`."] #[derive (Debug , Clone , Default)] #[unstable (feature = "sgx_platform" , issue = "56975")] pub struct TcpStreamMetadata { #[doc = " Local address of the TCP stream"] pub local_addr : Option < String > , #[doc = " Peer address of the TCP stream"] pub peer_addr : Option < String > , } impl FromRawFd for net :: TcpStream { type Metadata = TcpStreamMetadata ; #[inline] unsafe fn from_raw_fd (fd : RawFd , metadata : Self :: Metadata) -> net :: TcpStream { let fd = sys :: fd :: FileDesc :: from_inner (fd) ; let socket = sys :: net :: Socket :: from_inner ((fd , metadata . local_addr)) ; net :: TcpStream :: from_inner (sys :: net :: TcpStream :: from_inner ((socket , metadata . peer_addr))) } } #[doc = " Metadata for `TcpListener`."] #[derive (Debug , Clone , Default)] #[unstable (feature = "sgx_platform" , issue = "56975")] pub struct TcpListenerMetadata { #[doc = " Local address of the TCP listener"] pub local_addr : Option < String > , } impl FromRawFd for net :: TcpListener { type Metadata = TcpListenerMetadata ; #[inline] unsafe fn from_raw_fd (fd : RawFd , metadata : Self :: Metadata) -> net :: TcpListener { let fd = sys :: fd :: FileDesc :: from_inner (fd) ; let socket = sys :: net :: Socket :: from_inner ((fd , metadata . local_addr)) ; net :: TcpListener :: from_inner (sys :: net :: TcpListener :: from_inner (socket)) } } impl TryIntoRawFd for net :: TcpStream { #[inline] fn try_into_raw_fd (self) -> Result < RawFd , Self > { let (socket , peer_addr) = self . into_inner () . into_inner () ; match socket . try_into_inner () { Ok (fd) => Ok (fd . into_inner ()) , Err (socket) => { let sys = sys :: net :: TcpStream :: from_inner ((socket , peer_addr)) ; Err (net :: TcpStream :: from_inner (sys)) } } } } impl TryIntoRawFd for net :: TcpListener { #[inline] fn try_into_raw_fd (self) -> Result < RawFd , Self > { match self . into_inner () . into_inner () . try_into_inner () { Ok (fd) => Ok (fd . into_inner ()) , Err (socket) => { let sys = sys :: net :: TcpListener :: from_inner (socket) ; Err (net :: TcpListener :: from_inner (sys)) } } } }